import { createContext, useContext, useEffect, useState } from "react";
import type { ReactNode } from "react";
import { Icon } from "../components/Icon";
export type Theme = "light" | "dark" | "system";
const valid = (v: string | null): Theme =>
  v === "light" || v === "dark" ? v : "system";
const ThemeContext = createContext<{
  theme: Theme;
  setTheme: (v: Theme) => void;
}>({ theme: "system", setTheme: () => {} });
export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>(() => {
    try {
      return valid(localStorage.getItem("video-service-theme"));
    } catch {
      return "system";
    }
  });
  useEffect(() => {
    const media = matchMedia("(prefers-color-scheme: dark)");
    const apply = () => {
      const dark = theme === "dark" || (theme === "system" && media.matches);
      document.documentElement.dataset.theme = dark ? "dark" : "light";
      document.documentElement.style.colorScheme = dark ? "dark" : "light";
      document
        .querySelector('meta[name="theme-color"]')
        ?.setAttribute("content", dark ? "#0f0f0f" : "#ffffff");
    };
    apply();
    try {
      localStorage.setItem("video-service-theme", theme);
    } catch {
      /* Appearance still works without storage. */
    }
    media.addEventListener("change", apply);
    return () => media.removeEventListener("change", apply);
  }, [theme]);
  useEffect(() => {
    const sync = (e: StorageEvent) => {
      if (e.key === "video-service-theme") setTheme(valid(e.newValue));
    };
    window.addEventListener("storage", sync);
    return () => window.removeEventListener("storage", sync);
  }, []);
  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}
export function ThemeSettings() {
  const { theme, setTheme } = useContext(ThemeContext);
  return (
    <fieldset className="theme-settings">
      <legend>Оформление</legend>
      {(
        [
          ["light", "Светлая", "sun"],
          ["dark", "Тёмная", "moon"],
          ["system", "Как в системе", "monitor"],
        ] as const
      ).map(([value, label, icon]) => (
        <label key={value}>
          <Icon name={icon} size={20} />
          <span>{label}</span>
          <input
            type="radio"
            name="appearance"
            value={value}
            checked={theme === value}
            onChange={() => setTheme(value)}
          />
        </label>
      ))}
    </fieldset>
  );
}
import { useEffect, useRef, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { api } from "../api/client";
import type { Page } from "../api/client";

import { VideoCard, VideoSkeletons } from "../components/VideoCard";
import type { VideoCardData as Card } from "../components/VideoCard";
import { Icon } from "../components/Icon";
function Feed({ query, results }: { query: string; results: boolean }) {
  const [items, setItems] = useState<Card[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const pending = useRef<AbortController | null>(null);
  async function load(after: string | null) {
    pending.current?.abort();
    const controller = new AbortController();
    pending.current = controller;
    setLoading(true);
    setError("");
    const params = new URLSearchParams({ q: query, limit: "20" });
    if (after) params.set("cursor", after);
    try {
      const page = await api<Page<Card>>(`/videos?${params}`, {
        signal: controller.signal,
      });
      if (controller.signal.aborted) return;
      setItems((previous) =>
        after
          ? [
              ...new Map(
                [...previous, ...page.items].map((item) => [item.id, item]),
              ).values(),
            ]
          : page.items,
      );
      setCursor(page.next_cursor);
    } catch (e) {
      if (!controller.signal.aborted) setError((e as Error).message);
    } finally {
      if (!controller.signal.aborted) setLoading(false);
    }
  }
  useEffect(() => {
    void load(null);
    return () => pending.current?.abort();
  }, [query]);
  return (
    <section
      className={`feed-page${results ? " search-results" : ""}`}
      aria-busy={loading}
    >
      {results ? (
        <div className="page-heading">
          <h1>{query ? `Результаты: ${query}` : "Все видео"}</h1>
        </div>
      ) : (
        <h1 className="sr-only">Главная</h1>
      )}
      {error && (
        <div className="feed-error" role="alert">
          <p>{error}</p>
          <button onClick={() => void load(items.length ? cursor : null)}>
            Повторить
          </button>
        </div>
      )}
      <div className="video-grid">
        {items.map((item) => (
          <VideoCard key={item.id} video={item} />
        ))}
      </div>
      {loading && <VideoSkeletons />}
      {!loading && !error && !items.length && (
        <div className="empty-state">
          <span className="empty-icon">
            <Icon name={results ? "search" : "video"} size={56} />
          </span>
          <h2>{results ? "Ничего не найдено" : "Здесь пока нет видео"}</h2>
          <p>
            {results
              ? "Попробуйте другое название."
              : "Загрузите первое видео и поделитесь своей историей."}
          </p>
          <Link className="button-link" to={results ? "/" : "/upload"}>
            {results ? "На главную" : "Загрузить видео"}
          </Link>
        </div>
      )}
      {cursor && !error && (
        <button
          className="load-more secondary"
          disabled={loading}
          onClick={() => void load(cursor)}
        >
          Ещё видео
        </button>
      )}
    </section>
  );
}
export function HomePage({ results = false }: { results?: boolean }) {
  const [params] = useSearchParams();
  const query = results ? (params.get("q") || "").trim() : "";
  return <Feed key={`${results}:${query}`} query={query} results={results} />;
}
import { Icon } from "../../components/Icon";
import { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";

export function SearchBar() {
  const location = useLocation();
  const navigate = useNavigate();
  const [query, setQuery] = useState("");
  useEffect(() => {
    setQuery(new URLSearchParams(location.search).get("q") || "");
  }, [location.pathname, location.search]);
  return (
    <form
      className="search-bar"
      role="search"
      onSubmit={(e) => {
        e.preventDefault();
        const value = query.trim();
        navigate(value ? `/results?${new URLSearchParams({ q: value })}` : "/");
      }}
    >
      <input
        aria-label="Поиск видео"
        placeholder="Поиск"
        name="q"
        type="search"
        maxLength={200}
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <button aria-label="Найти видео" type="submit">
        <Icon name="search" />
      </button>
    </form>
  );
}
